#include <iostream>

class BuggyArray {
public:
    int size;
    int *data;

    BuggyArray(int s) : size(s), data(new int[s]) {}

    // Using compiler-default shallow copy
    BuggyArray(const BuggyArray &other) = default;

    ~BuggyArray() {
        // Intentionally avoiding delete[] here to prevent double-free in this demo,
        // highlighting the pointer aliasing issue.
    }
};

int main() {
    BuggyArray a(2);
    a.data[0] = 10;
    a.data[1] = 20;

    BuggyArray b = a; // Shallow copy: b.data points to the exact same buffer as a.data

    std::cout << "Before: a[0] = " << a.data[0] << ", b[0] = " << b.data[0] << "\n";
    b.data[0] = 99; // Mutating b inadvertently mutates a
    std::cout << "After:  a[0] = " << a.data[0] << ", b[0] = " << b.data[0] << "\n";
    std::cout << "Shared pointer address: " << (a.data == b.data ? "true" : "false") << "\n";

    delete[] a.data; // Cleanup
    return 0;
}

#include <iostream>

class DT {
private:
    int n;
    double *a;

public:
    DT() : n(0), a(nullptr) {}

    DT(int deg) : n(deg), a(new double[deg + 1]) {
        for (int i = 0; i <= n; ++i) {
            a[i] = 0.0;
        }
    }

    // User-defined Deep Copy Constructor
    DT(const DT &d) : n(d.n), a(nullptr) {
        if (d.a != nullptr) {
            a = new double[n + 1];
            for (int i = 0; i <= n; ++i) {
                a[i] = d.a[i];
            }
        }
    }

    ~DT() {
        delete[] a;
    }

    void setCoeff(int i, double val) {
        if (i >= 0 && i <= n && a != nullptr) {
            a[i] = val;
        }
    }

    void print(const char *name) const {
        std::cout << name << " (deg " << n << "): ";
        for (int i = 0; i <= n; ++i) {
            std::cout << a[i] << (i == n ? "" : " ");
        }
        std::cout << "\n";
    }
};

int main() {
    DT d(2);
    d.setCoeff(0, 1.5);
    d.setCoeff(1, 2.5);
    d.setCoeff(2, 3.5);

    DT u(d); // Invokes custom deep copy constructor

    std::cout << "Initial state:\n";
    d.print("d");
    u.print("u");

    // Mutating u independently
    u.setCoeff(0, 99.9);

    std::cout << "After modifying u[0]:\n";
    d.print("d");
    u.print("u");

    return 0;
}
